import * as T from './three.module.js';
export function hull(points){const p=points.sort((a,b)=>a.x-b.x||a.y-b.y),cross=(a,b,c)=>(b.x-a.x)*(c.y-a.y)-(b.y-a.y)*(c.x-a.x);const half=list=>{const out=[];for(const v of list){while(out.length>1&&cross(out.at(-2),out.at(-1),v)<=0)out.pop();out.push(v);}return out;};if(p.length<3)return p;const a=half(p),b=half([...p].reverse());return a.slice(0,-1).concat(b.slice(0,-1));}
export function meshOutline(mesh,camera,offset=null){mesh.updateWorldMatrix(true,false);const a=mesh.geometry.attributes.position,p=[];for(let i=0;i<a.count;i++){const v=new T.Vector3().fromBufferAttribute(a,i).applyMatrix4(mesh.matrixWorld);if(offset)v.add(offset);v.project(camera);p.push({x:v.x,y:v.y});}return hull(p);}
export function overlaps(a,b){if(a.length<3||b.length<3)return false;for(const poly of [a,b])for(let i=0;i<poly.length;i++){const p=poly[i],q=poly[(i+1)%poly.length],nx=p.y-q.y,ny=q.x-p.x;let amin=Infinity,amax=-Infinity,bmin=Infinity,bmax=-Infinity;for(const v of a){const d=v.x*nx+v.y*ny;amin=Math.min(amin,d);amax=Math.max(amax,d);}for(const v of b){const d=v.x*nx+v.y*ny;bmin=Math.min(bmin,d);bmax=Math.max(bmax,d);}if(amax<bmin||bmax<amin)return false;}return true;}
export function projectileTouchesBody(shot,before,next,body,camera){const origin=shot.position.clone();const swept=hull([...meshOutline(shot,camera,before.clone().sub(origin)),...meshOutline(shot,camera,next.clone().sub(origin))]);return overlaps(swept,meshOutline(body,camera));}
